usage.iconWithTooltip:
// Recommended pattern when the icon needs a tooltip on hover/click.
// StatCard does not manage the tooltip: the parent owns the content, the delay and the TooltipProvider.
<TooltipProvider delayDuration={200}>
  <StatCard
    label="Active Users"
    value="2,350"
    icon={<Users className="h-6 w-6" />}
    iconVariant="primary"
    trend={15.3}
    trendLabel="vs last month"
    iconWrapper={(badge) => (
      <Tooltip>
        <TooltipTrigger asChild>{badge}</TooltipTrigger>
        <TooltipContent>Users with at least one session in the last 30 days</TooltipContent>
      </Tooltip>
    )}
  />
</TooltipProvider>

